// @ts-check
/**
 * Tests: the window.App registry pilot #24 - the PDF-bundling helpers extracted
 * to features/pdf-bundle.js (their registrations re-homed from app.js). Non-cloud.
 *
 * Plus Tier-3 B5 (J10, invisible output fix) - pdf-bundle pagination:
 * - report slicing never cuts through a table row / heading (pure slicer +
 *   a real html2canvas render asserted via the recorded pagination diagnostics);
 * - a short report still renders one page (control);
 * - the notes section uses uniform A4 pages with the Notes Summary folded onto
 *   the first notes page (asserted from the generated bytes via pdf-lib).
 */
const { test, expect } = require('@playwright/test');
const { bootApp, collectConsoleErrors, uploadPdf } = require('./spec-helpers');

test.describe('window.App registry pilot - PDF bundling helpers', () => {
  test('registry wired: the 5 bundling helpers are functions on App', async ({ page }) => {
    await bootApp(page);
    const types = await page.evaluate(() => ({
      addReportPagesToPdf: typeof window.App?.addReportPagesToPdf,
      addNotesToPdf: typeof window.App?.addNotesToPdf,
      addHighlightsToPdf: typeof window.App?.addHighlightsToPdf,
      hasAnyHighlights: typeof window.App?.hasAnyHighlights,
      hasAnyNotes: typeof window.App?.hasAnyNotes,
    }));
    expect(types).toEqual({
      addReportPagesToPdf: 'function',
      addNotesToPdf: 'function',
      addHighlightsToPdf: 'function',
      hasAnyHighlights: 'function',
      hasAnyNotes: 'function',
    });
  });

  test('hasAnyHighlights/hasAnyNotes reflect page annotations', async ({ page }) => {
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    // Freshly loaded: no highlights/notes yet.
    expect(await page.evaluate(() => window.App.hasAnyHighlights())).toBe(false);
    expect(await page.evaluate(() => window.App.hasAnyNotes())).toBe(false);

    // Inject a highlight + a note into the first page's canvas, then re-check.
    await page.evaluate(() => {
      const c = window.App.getPageCanvases(window.state.pages[0])[0];
      c.annotations = c.annotations || {};
      c.annotations.highlights = c.annotations.highlights || [];
      c.annotations.notes = c.annotations.notes || [];
      c.annotations.highlights.push({});
      c.annotations.notes.push({});
    });
    expect(await page.evaluate(() => window.App.hasAnyHighlights())).toBe(true);
    expect(await page.evaluate(() => window.App.hasAnyNotes())).toBe(true);

    errors.assertNoErrors();
  });
});

test.describe('Tier-3 B5 - pdf-bundle pagination', () => {
  test('computeReportSliceBounds: a row straddling the cut lands whole on the next page', async ({ page }) => {
    await bootApp(page);

    const results = await page.evaluate(() => {
      const f = window.App.computeReportSliceBounds;
      return {
        // A 100px row straddles the 1000px cut -> the cut snaps to its top.
        straddle: f(3000, 1000, [{ top: 950, bottom: 1050 }]),
        // No rows -> plain page-height slices.
        plain: f(2500, 1000, []),
        // Short report -> a single slice (control).
        short: f(500, 1000, [{ top: 100, bottom: 140 }]),
        // A band taller than a page can't be kept whole -> ignored.
        tall: f(3000, 1000, [{ top: 500, bottom: 1600 }]),
      };
    });

    expect(results.straddle).toEqual([
      { y: 0, h: 950 },
      { y: 950, h: 1000 },
      { y: 1950, h: 1000 },
      { y: 2950, h: 50 },
    ]);
    expect(results.plain).toEqual([
      { y: 0, h: 1000 },
      { y: 1000, h: 1000 },
      { y: 2000, h: 500 },
    ]);
    expect(results.short).toEqual([{ y: 0, h: 500 }]);
    expect(results.tall).toEqual([
      { y: 0, h: 1000 },
      { y: 1000, h: 1000 },
      { y: 2000, h: 1000 },
    ]);
  });

  test('report pages: short report renders one page; a long one never cuts a row', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    // Seed counters + one marker each on page 1 (report rows = one per type).
    const seed = (n, offset) => page.evaluate(([count, off]) => {
      const ann = window.App.getActiveAnnotations(window.state.pages[0]);
      for (let i = 0; i < count; i++) {
        const id = 'b5-counter-' + (off + i);
        window.state.counters.push({ id, name: 'B5 Fixture Counter ' + (off + i), icon: null, color: '#e8c547' });
        ann.counterMarkers[id] = [{ x: 40 + i, y: 40 }];
      }
    }, [n, offset]);

    const runReport = () => page.evaluate(async () => {
      const doc = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4', orientation: 'p' });
      const pageCount = await window.App.addReportPagesToPdf(doc);
      const diag = window.App.getLastReportPagination();
      return { pageCount, docPages: doc.getNumberOfPages(), diag };
    });

    // CONTROL: 2 rows -> a single report page, one slice.
    await seed(2, 0);
    const short = await runReport();
    expect(short.pageCount).toBe(1);
    expect(short.docPages).toBe(1);
    expect(short.diag.slices.length).toBe(1);

    // LONG: ~70 more rows -> multiple pages; every internal slice boundary
    // must fall OUTSIDE every measured keep-together band (row / heading).
    await seed(70, 2);
    const long = await runReport();
    expect(long.pageCount).toBeGreaterThanOrEqual(2);
    expect(long.docPages).toBe(long.diag.slices.length);
    const boundaries = long.diag.slices.slice(1).map((s) => s.y);
    expect(boundaries.length).toBeGreaterThanOrEqual(1);
    const pageH = long.diag.pageHeightPx;
    // Strictly inside with a half-pixel tolerance: adjacent row rects tile at
    // fractional px, so a boundary exactly on a shared edge is a clean cut.
    for (const b of boundaries) {
      const cutRow = long.diag.keepRanges.find(
        (r) => r.bottom - r.top <= pageH && r.top < b - 0.5 && r.bottom > b + 0.5
      );
      expect(cutRow).toBeUndefined();
    }
    // Sanity: the fixture really produced row bands to keep together.
    expect(long.diag.keepRanges.length).toBeGreaterThan(70);

    errors.assertNoErrors();
  });

  test('notes: uniform A4 pages, Notes Summary folded onto the first notes page', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    // 3 notes across both pages.
    await page.evaluate(() => {
      const a0 = window.App.getActiveAnnotations(window.state.pages[0]);
      const a1 = window.App.getActiveAnnotations(window.state.pages[1]);
      a0.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'First fixture note - shares the summary page.' });
      a0.notes.push({ x: 60, y: 200, width: 150, fontSize: 14, text: 'Second fixture note.' });
      a1.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'Third fixture note, on page two.' });
    });

    const result = await page.evaluate(async () => {
      // doc = null: the builder makes its own A4 doc (BUNDLE-ONE-SHEET).
      const doc = await window.App.addNotesToPdf(null, {});
      const bytes = doc.output('arraybuffer');
      const pdf = await window.PDFLib.PDFDocument.load(bytes);
      const pages = pdf.getPages();
      const hasImage = (p) => {
        const res = p.node.Resources();
        if (!res) return false;
        const xo = res.lookupMaybe(window.PDFLib.PDFName.of('XObject'), window.PDFLib.PDFDict);
        return !!xo && xo.keys().length > 0;
      };
      return {
        pageCount: pdf.getPageCount(),
        sizes: pages.map((p) => p.getSize()),
        firstPageHasImage: hasImage(pages[0]),
      };
    });

    // Folded: 3 notes -> 3 pages (summary + note 1 share page 1), not 4.
    expect(result.pageCount).toBe(3);
    // Uniform: every notes page is A4 portrait (595.28 x 841.89 pt).
    for (const s of result.sizes) {
      expect(Math.abs(s.width - 595.28)).toBeLessThan(1);
      expect(Math.abs(s.height - 841.89)).toBeLessThan(1);
    }
    // The first page carries the note crop image alongside the summary text.
    expect(result.firstPageHasImage).toBe(true);

    errors.assertNoErrors();
  });

  // R25: the notes and highlights bundles render each sheet ONCE per export
  // (a one-sheet memo), not once per note or highlight; the pages they add are
  // unchanged (one per item, plus the summary).
  test('notes and highlights bundles render each sheet once per export (R25)', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    const result = await page.evaluate(async () => {
      const s = window.state, App = window.App;
      const a0 = App.getActiveAnnotations(s.pages[0]);
      const a1 = App.getActiveAnnotations(s.pages[1]);
      a0.highlights.push({ x1: 20, y1: 20, x2: 120, y2: 80 }, { x1: 150, y1: 150, x2: 260, y2: 230 });
      a1.highlights.push({ x1: 30, y1: 30, x2: 140, y2: 90 });
      a0.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'Note one.' }, { x: 60, y: 200, width: 150, fontSize: 14, text: 'Note two.' });
      a1.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'Note three.' });
      // Count the print renders per sheet (the export's own rasters; the view
      // renders with the display intent).
      const renders = [0, 0];
      s.pages.forEach((p, i) => {
        const orig = p.pdfPage.render.bind(p.pdfPage);
        p.pdfPage.render = (args) => { if (args && args.intent === 'print') renders[i]++; return orig(args); };
      });
      const count = async (fn) => {
        renders[0] = 0; renders[1] = 0;
        const doc = await fn();
        return { renders: renders.slice(), pages: doc.getNumberOfPages() };
      };
      return {
        highlights: await count(() => App.addHighlightsToPdf(null, {})),
        notes: await count(() => App.addNotesToPdf(null, {})),
      };
    });

    // One print render per sheet, however many items it carries.
    expect(result.highlights.renders).toEqual([1, 1]);
    expect(result.notes.renders).toEqual([1, 1]);
    // Highlights: the summary page, then one page per highlight.
    expect(result.highlights.pages).toBe(4);
    // Notes: the summary folds onto the first note's page (3 notes -> 3 pages).
    expect(result.notes.pages).toBe(3);

    errors.assertNoErrors();
  });
});

// BUNDLE-ONE-SHEET (DECOMPOSITION_MAP S05, defects N03 + N10 + the highlights
// overflow). Each test was written and run red against the old builders first.
test.describe('BUNDLE-ONE-SHEET - the notes and highlights bundles', () => {
  // N03: one sheet exported, report off, a bundle on. The old builders guessed
  // "is this a fresh doc?" from getNumberOfPages() > 1, so with exactly one
  // sheet page the summary table was drawn ON the sheet image.
  test('one sheet, report off: the summary gets its own page, never the sheet', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    const result = await page.evaluate(async () => {
      const s = window.state, App = window.App;
      const a0 = App.getActiveAnnotations(s.pages[0]);
      a0.highlights.push({ x1: 20, y1: 20, x2: 120, y2: 80 });
      a0.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'One-sheet fixture note.' });
      const run = async (bundleHighlights, bundleNotes) => {
        const { doc } = await App.runSpecificPagesExport({
          selections: { 0: 'marked', 1: 'exclude' },
          canvasMode: { 0: 'current' },
          exportScale: 1,
          includeReport: false,
          bundleHighlights,
          bundleNotes,
        });
        const pages = [];
        for (let n = 1; n <= doc.getNumberOfPages(); n++) {
          const ops = doc.internal.pages[n].join('\n');
          doc.setPage(n);
          pages.push({
            hasText: /\bBT\b/.test(ops),
            w: Math.round(doc.internal.pageSize.getWidth() * 10) / 10,
            h: Math.round(doc.internal.pageSize.getHeight() * 10) / 10,
          });
        }
        return pages;
      };
      return { highlights: await run(true, false), notes: await run(false, true) };
    });

    // Page 1 is the sheet (US Letter, 215.9 x 279.4 mm) with no text on it.
    for (const pages of [result.highlights, result.notes]) {
      expect(pages[0]).toEqual({ hasText: false, w: 215.9, h: 279.4 });
      // Page 2 is the A4 summary page.
      expect(pages[1]).toMatchObject({ hasText: true, w: 210, h: 297 });
    }
    // Highlights: sheet, summary, one page per highlight.
    expect(result.highlights.length).toBe(3);
    // Notes: sheet, then the summary with the one note folded under it.
    expect(result.notes.length).toBe(2);

    errors.assertNoErrors();
  });

  // N10: the sidebar buttons show when ANY layer holds a note or highlight,
  // and the bundles now collect from every layer too (the Summary has counted
  // every layer since MAP-SUMMARY-LAYERS). Each crop is cut from its own
  // layer's raster, so the item is in the picture.
  test('an item on a layer that is not active: the button opens a PDF with its page', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    await page.evaluate(() => {
      const s = window.state, App = window.App;
      const p0 = s.pages[0];
      const active = App.ensureActiveCanvas(p0);
      s.activeCanvasIdByPage = s.activeCanvasIdByPage || {};
      s.activeCanvasIdByPage[0] = active.id;
      const other = { id: 'bundle-other-layer', name: 'Second', annotations: App.makeAnnotations() };
      other.annotations.highlights.push({ x1: 20, y1: 20, x2: 120, y2: 80 });
      other.annotations.notes.push({ x: 40, y: 40, width: 150, fontSize: 14, text: 'Note on the second layer.' });
      p0.canvases.push(other);
      window.__bundleOpened = [];
      window.open = (url) => { window.__bundleOpened.push(url); return null; };
      window.__bundleRasterLayers = [];
      const orig = App.renderAnnotationsToContext;
      App.renderAnnotationsToContext = (...args) => {
        window.__bundleRasterLayers.push(args[4] === other.annotations ? 'other' : 'not-other');
        return orig(...args);
      };
      App.updateUI();
    });
    await expect(page.locator('#bundleHighlights')).not.toHaveCSS('display', 'none');
    await expect(page.locator('#bundleNotes')).not.toHaveCSS('display', 'none');
    // The buttons are bound by features/output.js through the registry.
    expect(await page.evaluate(() => typeof window.App.openBundlePdf)).toBe('function');

    const openAndRead = async (btnId) => {
      const before = await page.evaluate(() => window.__bundleOpened.length);
      await page.evaluate((id) => document.getElementById(id).click(), btnId);
      await page.waitForFunction((n) => window.__bundleOpened.length > n, before, { timeout: 60000 });
      return page.evaluate(async () => {
        const url = window.__bundleOpened[window.__bundleOpened.length - 1];
        const bytes = await (await fetch(url)).arrayBuffer();
        const L = window.PDFLib;
        const pdf = await L.PDFDocument.load(bytes);
        // jsPDF shares one Resources dict across pages, so ask the page's own
        // content stream whether it paints an image (the `Do` operator).
        const drawsImage = (p) => {
          const c = p.node.Contents();
          if (!c) return false;
          const streams = c instanceof L.PDFArray ? c.asArray().map((r) => pdf.context.lookup(r)) : [c];
          return streams.some((st) => /\bDo\b/.test(new TextDecoder('latin1').decode(st.getContents())));
        };
        return { pageCount: pdf.getPageCount(), images: pdf.getPages().map(drawsImage) };
      });
    };

    // Highlights: the summary page, then the highlight's page with its crop.
    const high = await openAndRead('bundleHighlights');
    expect(high).toEqual({ pageCount: 2, images: [false, true] });
    // Notes: the summary with the note folded under it, crop included.
    const notes = await openAndRead('bundleNotes');
    expect(notes).toEqual({ pageCount: 1, images: [true] });
    // Both crops were cut from the second layer's raster.
    const layers = await page.evaluate(() => window.__bundleRasterLayers);
    expect(layers).toContain('other');
    expect(layers).not.toContain('not-other');

    errors.assertNoErrors();
  });

  // The Highlights Summary had no page-overflow guard (the Notes one did), so
  // past about 36 sheets its rows ran off the bottom of the page.
  test('a long summary table breaks onto the next page (highlights and notes)', async ({ page }) => {
    test.setTimeout(120000);
    const errors = collectConsoleErrors(page);

    await bootApp(page);
    await uploadPdf(page);

    const result = await page.evaluate(async () => {
      const s = window.state, App = window.App;
      const saved = s.pages;
      const p0 = saved[0];
      // 40 sheets, each with one highlight and one note on its only layer.
      s.pages = Array.from({ length: 40 }, (_, i) => {
        const ann = App.makeAnnotations();
        ann.highlights.push({ x1: 20, y1: 20, x2: 60, y2: 50 });
        ann.notes.push({ x: 40, y: 40, width: 100, fontSize: 10, text: 'N' + (i + 1) });
        return { ...p0, label: 'Sheet ' + (i + 1), canvases: [{ id: 'long-' + i, name: 'Main', annotations: ann }] };
      });
      const measure = async (build) => {
        const doc = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4', orientation: 'p' });
        const texts = [];
        const origText = doc.text.bind(doc);
        doc.text = (t, x, y, o) => {
          texts.push({ t: String(t), y, pageH: doc.internal.pageSize.getHeight() });
          return origText(t, x, y, o);
        };
        await build(doc);
        return texts;
      };
      try {
        return {
          highlights: await measure((doc) => App.addHighlightsToPdf(doc, { scale: 1 })),
          notes: await measure((doc) => App.addNotesToPdf(doc, { scale: 1 })),
        };
      } finally {
        s.pages = saved;
      }
    });

    for (const texts of [result.highlights, result.notes]) {
      // Every sheet has its summary row...
      expect(texts.filter((x) => /^Sheet \d+$/.test(x.t)).length).toBe(40);
      // ...and no text of any kind lands below the page's bottom margin.
      const off = texts.filter((x) => x.y > x.pageH - 10);
      expect(off).toEqual([]);
    }

    errors.assertNoErrors();
  });
});
